q.ta:
பிழையைக் கண்டுபிடிக்கவும்:
def full_finetune_params(L, d, m):
    return L * m * (d + d)

uth_example:
model = {"layers": 32, "d": 4096}
plans = {
    "q,v only": {"matrices": 2, "r": 8},
    "q,k,v,o": {"matrices": 4, "r": 8},
    "q,k,v,o r=64": {"matrices": 4, "r": 64},
}

full = model["layers"] * 4 * model["d"] ** 2         # full fine-tune of attention
budget = {}
for name, p in plans.items():
    lora = model["layers"] * p["matrices"] * p["r"] * (2 * model["d"])
    budget[name] = (lora, round(lora / full * 100, 3))

print(f"full attention fine-tune: {full:,} params")
for name, (params, pct) in budget.items():
    print(f"{name:14} {params:>11,} params = {pct}%")
